    "Script": "PageCreator = {
    init: async function (app, container, parent, callback, dialog) {
        app = app || session.app;
        container = container || $(".component[name=PageCreator]");
        api.addToMetaCache([
        {
        "Name": "Core",
        "Types": [
            [meta[Core/Layout]]
        ]
    }]);
        var layoutModel = new kendo.data.ObservableObject({
            Name: "",
            ParentId: parent ? parent.Id : null,
            AppId: parent ? parent.AppId : app.Id,
            ShowOnMenus: false,
            Path: null,
            Layout: "Default",
            Order: 0,
            Contents: [],
            PageInfo: [{
                CultureId: '',
                Title: null,
                Description: '',
                Keywords: ''
            }
            ]
        });
        var layoutDatasource = await model.getDatasource({
            endpoint: "ContentManagement/Layout",
            odataAppend: "?$filter=AppId eq " + app.Id + "&$select=Name,Html"
        });
        $("#LayoutDropDown", container).kendoDropDownList({
            dataTextField: "Name",
            dataValueField: "Name",
            dataSource: layoutDatasource,
            value: (parent) ? parent.Layout : "Default",
            change: function (e) { layoutModel.Layout = e.sender.value(); }
        });
        kendo.bind(container, layoutModel);
        container.data("model", layoutModel);
        $("button[name=submit]", container).click((e) => PageCreator.createPage(e, layoutModel, callback, dialog));
    },


    createPage: async function (e, layoutModel, callback, dialog) {
        e.preventDefault();
        await api.add("ContentManagement/Page", layoutModel.toJSON()).then((newPage) => {
            notification.success("[resource_description[added]]");
            if(dialog) { dialog.events.close(); }
            if(callback) { callback("create", newPage); }
        }).catch((err) => { error(err); });
    }
};
