  {
    "Name": "AppManagement",
    "Key": "ContentManagement",
    "ResourceKey": "ContentManagement",
    "Script": "[script[Bundle.Monaco.Web]]
AppManagement = {
    toolbar: true,

    init: async function (app, container) {
        app = app || session.app;
        container = container ? $(container) : $(".component[name=AppManagement]").first();
        app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);

        if (AppManagement.toolbar) {
            $("[name=appToolbar]", container).kendoToolBar({
                items: [
                    {
                        text: "[resource_displayname[save]]",
                        type: "button",
                        template: `
                            <button class="btn btn-primary" name="appSave">
                                <span class='k-icon k-i-save'></span> [resource_displayname[Save]]
                            </button>`
                    },
                    {
                        text: "[resource_displayname[migrate]]",
                        type: "button",
                        template: `
                            <button class="btn btn-primary" name="appMigrate" data-bs-toggle="modal" data-bs-target="#app-migrator-model">
                                <span class='k-icon k-i-arrow-up'></span> [resource_displayname[Migrate]]
                            </button>`
                    }
                ]
            });
        } else {
            $("[name=appToolbar]", container).remove();
        }

        var tabManagers = {
            pages: "PageManagement",
            theming: "AppTheming",
            cultures: "CultureManagement",
            layouts: "LayoutManagement",
            templates: "TemplateManagement",
            components: "ComponentManagement",
            resources: "ResourceManagement",
            roles: "RoleManagement"
        };

        var instanceId = container.data("appManagementInstanceId") || Guid();
        container.data("appManagementInstanceId", instanceId);

        $(".nav-link[data-bs-toggle=tab]", container).each(function() {
            var tab = $(this);
            var originalTarget = tab.attr("data-bs-target");
            var originalPaneId = originalTarget.replace(/^#/, "");
            var pane = $(".tab-pane", container).filter(function() {
                return this.id === originalPaneId;
            });

            if (pane.length === 1) {
                var paneId = originalPaneId + "-" + instanceId;
                var tabId = (tab.attr("id") || originalPaneId + "-tab") + "-" + instanceId;
                tab.attr("id", tabId);
                tab.attr("data-bs-target", "#" + paneId);
                tab.attr("aria-controls", paneId);
                tab.data("appManagementPane", pane.attr("name"));
                pane.attr("id", paneId);
                pane.attr("aria-labelledby", tabId);
            }
        });

        async function initializeManager(tab) {
            var paneName = tab.data("appManagementPane");
            var pane = $(".tab-pane[name=" + paneName + "]", container);
            var managerName = tabManagers[paneName];
            var component = managerName
                ? $(".component[name=" + managerName + "]", pane).first()
                : $();

            if (managerName
                && component.length === 1
                && !component.data("managerInitialised")
                && !component.data("managerLoading")) {
                component.data("managerLoading", true);

                try {
                    await window[managerName].init(app, component);
                    component.data("managerInitialised", true);
                } catch (err) {
                    error(err);
                } finally {
                    component.removeData("managerLoading");
                }
            }

            AppManagement.resizePane(pane);
        }

        $(".nav-link[data-bs-toggle=tab]", container).off("click.appManagement").on("click.appManagement", async function() {
            await initializeManager($(this));
        });

        var activeTab = $(".nav-link[data-bs-toggle=tab].active", container).first();

        if (activeTab.length === 1) {
            await initializeManager(activeTab);
        }

        await new Promise(function(resolve) {
            requestAnimationFrame(function() {
                requestAnimationFrame(resolve);
            });
        });

        if ($(".tab-pane[name=config]", container)[0].childElementCount === 0) {
            var configEditor = new MonacoEditor($(".tab-pane[name=config]", container)[0], {
                code: JSON.stringify(app.Config, null, 2),
                language: "json",
                automaticLayout: true
            });
            configEditor.onChange = () => app.ConfigJson = configEditor.getValue();
            configEditor.init();
            $(".tab-pane[name=config]", container).data("configEditor", configEditor);
            $("[name=appSave]", container).click(() => AppManagement.save(app, configEditor));
            $("[name=appMigrate]", container).click(() => AppManagement.migrate(app, container));
        }
    },

    resizePane: function (pane) {
        $(".k-grid", pane).each(function() {
            var grid = $(this).data("kendoGrid");
            if (grid) grid.resize(true);
        });

        $(".monaco-editor", pane).each(function() {
            var editor = $(this).data("monacoEditor");
            if (editor && editor.layout) editor.layout();
        });
    },

    migrate: async function (app, container) {
        var element = $("[name=AppMigrator]", container);
        await AppMigrator.init(app, element, app);
    },

    save: async function (app, configEditor) {
        var formattedConfig;
        try {
            formattedConfig = JSON.stringify(JSON.parse(configEditor.getValue()), null, 2);
        } catch(err) {
            error("[resource_displayname[AppConfigParsingError]]");
            return;
        }

        var newApp = {
            ConfigJson: formattedConfig,
            Cultures: app.Cultures,
            DefaultCultureId: app.DefaultCultureId,
            DefaultTheme: app.DefaultTheme,
            Domain: app.Domain,
            Id: app.Id,
            Name: app.Name,
            TenantId: app.TenantId
        };

        notification.info("[resource_displayname[saving]]");
        await api.update("ContentManagement/App(" + app.Id + ")", newApp).then(() => {
            app.ConfigJson = formattedConfig;
            app.Config = JSON.parse(formattedConfig);
            configEditor.editor.setValue(formattedConfig);
            notification.success("[resource_displayname[saved]]");
        }).catch((err) => error(err));
    }
};",
