    "Script": "CoreManagement = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=CoreManagement]");
        api.addToMetaCache([
                    {
                        Name: "ContentManagement",
                        Types: [
                            [meta[ContentManagement/App]],
                            [meta[ContentManagement/Culture]]
                        ]
                    }
                ]);

        var cultureDataSource = await model.getDatasource({endpoint: "ContentManagement/Culture"});
        var ds = await model.getDatasource({ endpoint: "ContentManagement/App", odataAppend: "?$expand=Cultures" });
        var appGrid = new GridWidget(container, ds);
        appGrid.groupable = false;
        appGrid.toolbar = "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[newapp]]</button>";
        appGrid.columns = [
            { field: "Name", title: "[resource_shortdisplayname[name]]" },
            { field: "Domain", title: "[resource_shortdisplayname[domain]]" },
            { field: "DefaultTheme", title: "[resource_shortdisplayname[defaulttheme]]" },
            { title: "[resource_displayname[visit]]", width: 96, editable: false, template: function (data) { return "<a class='btn btn-sm btn-outline-primary' href='https://" + kendo.htmlEncode(data.Domain || "") + "/' target='_blank' rel='noopener'><span class='k-icon k-i-share'></span>[resource_displayname[visit]]</a>"; } },
            { 
                field: "DefaultCultureId", 
                title: "[resource_shortdisplayname[defaultculture]]", 
                editor: function(container, options) {
                    $("<input name='" + options.field + "' />").appendTo(container).kendoDropDownList({
                        template: "#=Name# (#=Id#)",
                        dataTextField: "Id",
                        dataValueField: "Id",
                        dataSource: cultureDataSource
                    }).data("kendoDropDownList").value(options.model.DefaultCultureId);
                } 
            }
        ];
        appGrid.commands.push({name: "save", icon: "k-i-save", text: "[resource_displayname[save]]"});
        appGrid.commands.push({name: "migrate", icon: "k-i-copy", text: "[resource_displayname[migrate]]"});
        appGrid.commands.push({name: "destroy", icon: "k-i-trash", text: "[resource_displayname[delete]]"});
        appGrid.detailTemplate = "<div name='CoreManagementExpanded'></div>";
        appGrid.detailExpand = (e) => CoreManagement.expand(e, appGrid);
        appGrid.dataBound = function() {
            $("[name=migrate]", appGrid.gridElement).on("click", (e) => CoreManagement.migrate(e, appGrid));
            $("[name=destroy]", appGrid.gridElement).on("click", (e) => CoreManagement.destroy(e, appGrid));
            $("[name=save]", appGrid.gridElement).on("click", (e) => CoreManagement.save(e, appGrid));
        };
        await appGrid.init();
        $("button[name=create]", appGrid.gridElement).off('click').on("click",  (e) => CoreManagement.create(e, appGrid));
    },

    expand: function (e, grid) {
        var container = $(e.detailRow);
        var app = grid.dataItem(e.masterRow);
        if ($(container).find("div[name=tabs]").length === 0) {
            var host = $("[name='CoreManagementExpanded']", container);
            loadComponent(host, "AppManagement", async function() {
                AppManagement.toolbar = false;
                var component = $(".component[name=AppManagement]", host);
                await AppManagement.init(app, component);
                $(e.masterRow).find("[name=save]").off("click").on("click", function(saveEvent) {
                    var configEditor = $(".tab-pane[name=config]", component).data("configEditor");
                    if (configEditor) {
                        app.ConfigJson = configEditor.getValue();
                    }
                    CoreManagement.save(saveEvent, grid, app);
                });
            });
        }
    },

    create: async function (e, grid) {
        e.preventDefault();
        var newApp = kendo.observable({  Id: 0, Name: "", Domain: "", DefaultCultureId: "", DefaultTheme: "Default" });
        var newAppDialog = new Dialog({title: "[resource_displayname[newapp]]"});
        newAppDialog.template = $("[name=newApp]").first().html();
        newAppDialog.events.create = async function() {
            await api.add("ContentManagement/App", newApp.toJSON()).then(() => {
                newAppDialog.events.close();
                notification.success('[resource_displayname[AppCreated]]'.replace("[name]", newApp.Name));
                grid.refresh();
            }).catch((err) => error(err));
        };
        newAppDialog.init(() => {
            kendo.bind($(newAppDialog.element), newApp);
        });
    },

    destroy: function (e, grid) {
        var d = new ConfirmDialog({
            question: "[resource_displayname[AreYouSure]]",
            title: "[resource_displayname[AreYouSure]]",
            confirm: "[resource_displayname[Confirm]]",
            close: "[resource_displayname[Cancel]]"
        });

        d.events.confirm = async function () {
            var appRow = grid.dataItem($(e.currentTarget).closest("tr"));
            await appRow.destroy(e);
            notification.success("[resource_description[AppDeleted]]");
            grid.refresh();
            d.events.close();
        };
        d.init();
    },

    save: async function (e, grid, app) {
        e.preventDefault();
        // perform the save
        if(!app) {
            app = grid.dataItem($(e.currentTarget).closest("tr"));
        }

        await app.save(e);
        notification.success("[resource_displayname[AppSaved]]");
        grid.refresh();
    },

    migrate: function (e, grid) {
        var app = grid.dataItem($(e.currentTarget).closest("tr"));
        var migrateDialog = new Dialog({title: "[resource_displayname[MigrateApp]]", width: 620, height: "auto" });
        migrateDialog.init();
        loadComponent(migrateDialog.element, "AppMigrator", function (c) {
            AppMigrator.init(session.app, migrateDialog.element, app, migrateDialog);
        });
    }
};",
